mkitem!{mktrait!{# [doc = " Windows-specific extensions to the [`process::Command`] builder."] # [doc = ""] # [doc = " This trait is sealed: it cannot be implemented outside the standard library."] # [doc = " This is so that future additional methods are not breaking changes."] # [stable (feature = "windows_process_extensions" , since = "1.16.0")] pub trait CommandExt : Sealed { # [doc = " Sets the [process creation flags][1] to be passed to `CreateProcess`."] # [doc = ""] # [doc = " These will always be ORed with `CREATE_UNICODE_ENVIRONMENT`."] # [doc = ""] # [doc = " [1]: https://docs.microsoft.com/en-us/windows/win32/procthread/process-creation-flags"] # [stable (feature = "windows_process_extensions" , since = "1.16.0")] fn creation_flags (& mut self , flags : u32) -> & mut process :: Command ; # [doc = " Sets the field `wShowWindow` of [STARTUPINFO][1] that is passed to `CreateProcess`."] # [doc = " Allowed values are the ones listed in"] # [doc = " <https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-showwindow>"] # [doc = ""] # [doc = " [1]: <https://learn.microsoft.com/en-us/windows/win32/api/processthreadsapi/ns-processthreadsapi-startupinfow>"] # [unstable (feature = "windows_process_extensions_show_window" , issue = "127544")] fn show_window (& mut self , cmd_show : u16) -> & mut process :: Command ; # [doc = " Forces all arguments to be wrapped in quote (`\"`) characters."] # [doc = ""] # [doc = " This is useful for passing arguments to [MSYS2/Cygwin][1] based"] # [doc = " executables: these programs will expand unquoted arguments containing"] # [doc = " wildcard characters (`?` and `*`) by searching for any file paths"] # [doc = " matching the wildcard pattern."] # [doc = ""] # [doc = " Adding quotes has no effect when passing arguments to programs"] # [doc = " that use [msvcrt][2]. This includes programs built with both"] # [doc = " MinGW and MSVC."] # [doc = ""] # [doc = " [1]: <https://github.com/msys2/MSYS2-packages/issues/2176>"] # [doc = " [2]: <https://msdn.microsoft.com/en-us/library/17w5ykft.aspx>"] # [unstable (feature = "windows_process_extensions_force_quotes" , issue = "82227")] fn force_quotes (& mut self , enabled : bool) -> & mut process :: Command ; # [doc = " Append literal text to the command line without any quoting or escaping."] # [doc = ""] # [doc = " This is useful for passing arguments to applications that don't follow"] # [doc = " the standard C run-time escaping rules, such as `cmd.exe /c`."] # [doc = ""] # [doc = " # Batch files"] # [doc = ""] # [doc = " Note the `cmd /c` command line has slightly different escaping rules than batch files"] # [doc = " themselves. If possible, it may be better to write complex arguments to a temporary"] # [doc = " `.bat` file, with appropriate escaping, and simply run that using:"] # [doc = ""] # [doc = " ```no_run"] # [doc = " # use std::process::Command;"] # [doc = " # let temp_bat_file = \"\";"] # [doc = " # #[allow(unused)]"] # [doc = " let output = Command::new(\"cmd\").args([\"/c\", &format!(\"\\\"{temp_bat_file}\\\"\")]).output();"] # [doc = " ```"] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " Run a batch script using both trusted and untrusted arguments."] # [doc = ""] # [doc = " ```no_run"] # [doc = " #[cfg(windows)]"] # [doc = " // `my_script_path` is a path to known bat file."] # [doc = " // `user_name` is an untrusted name given by the user."] # [doc = " fn run_script("] # [doc = "     my_script_path: &str,"] # [doc = "     user_name: &str,"] # [doc = " ) -> Result<std::process::Output, std::io::Error> {"] # [doc = "     use std::io::{Error, ErrorKind};"] # [doc = "     use std::os::windows::process::CommandExt;"] # [doc = "     use std::process::Command;"] # [doc = ""] # [doc = "     // Create the command line, making sure to quote the script path."] # [doc = "     // This assumes the fixed arguments have been tested to work with the script we're using."] # [doc = "     let mut cmd_args = format!(r#\"\"{my_script_path}\" \"--features=[a,b,c]\"\"#);"] # [doc = ""] # [doc = "     // Make sure the user name is safe. In particular we need to be"] # [doc = "     // cautious of ascii symbols that cmd may interpret specially."] # [doc = "     // Here we only allow alphanumeric characters."] # [doc = "     if !user_name.chars().all(|c| c.is_alphanumeric()) {"] # [doc = "         return Err(Error::new(ErrorKind::InvalidInput, \"invalid user name\"));"] # [doc = "     }"] # [doc = ""] # [doc = "     // now we have validated the user name, let's add that too."] # [doc = "     cmd_args.push_str(\" --user \");"] # [doc = "     cmd_args.push_str(user_name);"] # [doc = ""] # [doc = "     // call cmd.exe and return the output"] # [doc = "     Command::new(\"cmd.exe\")"] # [doc = "         .arg(\"/c\")"] # [doc = "         // surround the entire command in an extra pair of quotes, as required by cmd.exe."] # [doc = "         .raw_arg(&format!(\"\\\"{cmd_args}\\\"\"))"] # [doc = "         .output()"] # [doc = " }"] # [doc = " ````"] # [stable (feature = "windows_process_extensions_raw_arg" , since = "1.62.0")] fn raw_arg < S : AsRef < OsStr > > (& mut self , text_to_append_as_is : S) -> & mut process :: Command ; # [doc = " When [`process::Command`] creates pipes, request that our side is always async."] # [doc = ""] # [doc = " By default [`process::Command`] may choose to use pipes where both ends"] # [doc = " are opened for synchronous read or write operations. By using"] # [doc = " `async_pipes(true)`, this behavior is overridden so that our side is"] # [doc = " always async."] # [doc = ""] # [doc = " This is important because if doing async I/O a pipe or a file has to be"] # [doc = " opened for async access."] # [doc = ""] # [doc = " The end of the pipe sent to the child process will always be synchronous"] # [doc = " regardless of this option."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(windows_process_extensions_async_pipes)]"] # [doc = " use std::os::windows::process::CommandExt;"] # [doc = " use std::process::{Command, Stdio};"] # [doc = ""] # [doc = " # let program = \"\";"] # [doc = ""] # [doc = " Command::new(program)"] # [doc = "     .async_pipes(true)"] # [doc = "     .stdin(Stdio::piped())"] # [doc = "     .stdout(Stdio::piped())"] # [doc = "     .stderr(Stdio::piped());"] # [doc = " ```"] # [unstable (feature = "windows_process_extensions_async_pipes" , issue = "98289")] fn async_pipes (& mut self , always_async : bool) -> & mut process :: Command ; # [doc = " Executes the command as a child process with the given"] # [doc = " [`ProcThreadAttributeList`], returning a handle to it."] # [doc = ""] # [doc = " This method enables the customization of attributes for the spawned"] # [doc = " child process on Windows systems."] # [doc = " Attributes offer extended configurability for process creation,"] # [doc = " but their usage can be intricate and potentially unsafe."] # [doc = ""] # [doc = " # Note"] # [doc = ""] # [doc = " By default, stdin, stdout, and stderr are inherited from the parent"] # [doc = " process."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(windows_process_extensions_raw_attribute)]"] # [doc = " use std::os::windows::io::AsRawHandle;"] # [doc = " use std::os::windows::process::{CommandExt, ProcThreadAttributeList};"] # [doc = " use std::process::Command;"] # [doc = ""] # [doc = " # struct ProcessDropGuard(std::process::Child);"] # [doc = " # impl Drop for ProcessDropGuard {"] # [doc = " #     fn drop(&mut self) {"] # [doc = " #         let _ = self.0.kill();"] # [doc = " #     }"] # [doc = " # }"] # [doc = " #"] # [doc = " let parent = Command::new(\"cmd\").spawn()?;"] # [doc = " let parent_process_handle = parent.as_raw_handle();"] # [doc = " # let parent = ProcessDropGuard(parent);"] # [doc = ""] # [doc = " const PROC_THREAD_ATTRIBUTE_PARENT_PROCESS: usize = 0x00020000;"] # [doc = " let mut attribute_list = ProcThreadAttributeList::build()"] # [doc = "     .attribute(PROC_THREAD_ATTRIBUTE_PARENT_PROCESS, &parent_process_handle)"] # [doc = "     .finish()"] # [doc = "     .unwrap();"] # [doc = ""] # [doc = " let mut child = Command::new(\"cmd\").spawn_with_attributes(&attribute_list)?;"] # [doc = " #"] # [doc = " # child.kill()?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] # [unstable (feature = "windows_process_extensions_raw_attribute" , issue = "114854")] fn spawn_with_attributes (& mut self , attribute_list : & ProcThreadAttributeList < '_ > ,) -> io :: Result < process :: Child > ; # [doc = " When true, sets the `STARTF_RUNFULLSCREEN` flag on the [STARTUPINFO][1] struct before passing it to `CreateProcess`."] # [doc = ""] # [doc = " [1]: https://learn.microsoft.com/en-us/windows/win32/api/processthreadsapi/ns-processthreadsapi-startupinfoa"] # [unstable (feature = "windows_process_extensions_startupinfo" , issue = "141010")] fn startupinfo_fullscreen (& mut self , enabled : bool) -> & mut process :: Command ; # [doc = " When true, sets the `STARTF_UNTRUSTEDSOURCE` flag on the [STARTUPINFO][1] struct before passing it to `CreateProcess`."] # [doc = ""] # [doc = " [1]: https://learn.microsoft.com/en-us/windows/win32/api/processthreadsapi/ns-processthreadsapi-startupinfoa"] # [unstable (feature = "windows_process_extensions_startupinfo" , issue = "141010")] fn startupinfo_untrusted_source (& mut self , enabled : bool) -> & mut process :: Command ; # [doc = " When specified, sets the following flags on the [STARTUPINFO][1] struct before passing it to `CreateProcess`:"] # [doc = " - If `Some(true)`, sets `STARTF_FORCEONFEEDBACK`"] # [doc = " - If `Some(false)`, sets `STARTF_FORCEOFFFEEDBACK`"] # [doc = " - If `None`, does not set any flags"] # [doc = ""] # [doc = " [1]: https://learn.microsoft.com/en-us/windows/win32/api/processthreadsapi/ns-processthreadsapi-startupinfoa"] # [unstable (feature = "windows_process_extensions_startupinfo" , issue = "141010")] fn startupinfo_force_feedback (& mut self , enabled : Option < bool >) -> & mut process :: Command ; }}}
